import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        while (true) {
            StringBuilder res = new StringBuilder();
            boolean changed = false;
            for (int i = 0; i < s.length();) {
                int j = i + 1;
                while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
                if (j - i > 1) changed = true;
                res.append((long) (s.charAt(i) - '0') * (j - i));  // digit sum of the run
                i = j;
            }
            if (!changed) break;
            s = res.toString();
        }
        System.out.println(s);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	s := readToken()
	for {
		res := []byte{}
		changed := false
		for i := 0; i < len(s); {
			j := i + 1
			for j < len(s) && s[j] == s[i] {
				j++
			}
			if j-i > 1 {
				changed = true
			}
			res = strconv.AppendInt(res, int64(s[i]-'0')*int64(j-i), 10) // digit sum of the run
			i = j
		}
		if !changed {
			break
		}
		s = string(res)
	}
